import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/Academics.css";

export default function Academics() {
  const [data, setData] = useState({});

  useEffect(() => {
    axios.get("http://localhost:5000/api/academics")
      .then(res => setData(res.data || {}))
      .catch(err => console.error(err));
  }, []);

  return (
    <div className="academics-page">
      <h1 className="academics-title">Academics</h1>

      {Object.entries(data).map(([section, html]) => (
        <div key={section} className="academics-section">
          <h2 className="section-title">{section.charAt(0).toUpperCase() + section.slice(1)}</h2>
          <div
            className="ql-editor academics-content"
            dangerouslySetInnerHTML={{ __html: html }}
          ></div>
        </div>
      ))}
    </div>
  );
}
